<?php
require_once __DIR__.'/../includes/database.php';require_once __DIR__.'/../includes/push.php';
function push_check($ok,$why){if(!$ok)throw new RuntimeException($why);}
$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);initialize_database($db);initialize_database($db);
foreach(['Uno','Dos'] as $i=>$name)stock_query($db,'INSERT INTO users(name,public_name,email,password_hash) VALUES(?,?,?,?)',[$name,$name,$i.'@example.invalid','x']);
