$keys=push_keys($db);push_check(strlen($keys['public_key'])===87&&strlen($keys['private_key'])===43,'persistent VAPID keys');push_check(push_keys($db)===$keys,'same keys across calls');
$client=\Minishlink\WebPush\VAPID::createVapidKeys();$input=['endpoint'=>'https://fcm.googleapis.com/fcm/send/fixture','keys'=>['p256dh'=>$client['publicKey'],'auth'=>rtrim(strtr(base64_encode(random_bytes(16)),'+/','-_'),'=')]];
foreach(['http://fcm.googleapis.com/fcm/x','https://127.0.0.1/x','https://fcm.googleapis.com.evil.invalid/x','https://user@fcm.googleapis.com/x','https://fcm.googleapis.com:8443/x'] as $url){try{push_validate([...$input,'endpoint'=>$url]);throw new RuntimeException('SSRF accepted');}catch(CatalogException $e){push_check($e->status===422,'endpoint rejected');}}
stock_query($db,"INSERT INTO notifications(user_id,event_key,type,title,body) VALUES(1,'old','achievement','Viejo','No debe enviarse')");$id=push_subscribe($db,1,$device,$input);
$l=stock_generate($db,2);$p=stock_claim($db,$l['code'],2);stock_query($db,"INSERT INTO pallet_access(pallet_id,user_id,status) VALUES(?,1,'pending')",[$p['id']]);
stock_query($db,'INSERT INTO notifications(user_id,event_key,type,title,body) VALUES(?,?,?,?,?)',[1,'pallet-invite:'.$p['id'].':1:new','stock_invitation','Invitación','Dos te invitó al palet']);
stock_query($db,"INSERT INTO notifications(user_id,event_key,type,title,body) VALUES(1,'referral','referral_joined','Referido','No es push')");
$now=(new DateTimeImmutable('now',new DateTimeZone('America/Buenos_Aires')))->setTime(10,0);push_prepare($db,$now);push_prepare($db,$now);push_check((int)stock_query($db,'SELECT COUNT(*) FROM push_jobs')->fetchColumn()===1,'only new allowed notice once');
$sent=[];$fake=function($db,$s,$payload)use(&$sent){$sent[]=$payload;return ['success'=>true,'status'=>201];};push_check(push_dispatch($db,$fake)===1,'dispatched');push_check(push_dispatch($db,$fake)===0,'no duplicate');push_check(count($sent)===1&&!empty($sent[0]['receipt'])&&$sent[0]['user']===1,'scoped receipt');push_check((int)stock_query($db,'SELECT COUNT(*) FROM notifications WHERE read_at IS NOT NULL')->fetchColumn()===0,'delivery never reads inbox');
$own=stock_generate($db,1);$own=stock_claim($db,$own['code'],1);$date=(new DateTimeImmutable('today',new DateTimeZone('America/Buenos_Aires')))->format('Y-m-d');stock_save_product($db,1,['pallet_id'=>$own['id'],'ean'=>'96385074','name'=>'Prueba','amount'=>10,'expires'=>$date]);
stock_query($db,"UPDATE push_subscriptions SET expiry_day='' WHERE id=?",[$id]);push_prepare($db,$now);push_check((int)stock_query($db,"SELECT COUNT(*) FROM push_jobs WHERE kind='expiry'")->fetchColumn()===1,'daily aggregate');push_dispatch($db,$fake);push_check(str_contains(end($sent)['body'],'vencen hoy'),'expiry summary');
push_enqueue($db,$id,'revoke','test',['title'=>'Prueba','body'=>'Pendiente','url'=>'cuenta.php']);stock_query($db,'DELETE FROM account_devices WHERE user_id=1');push_check(push_dispatch($db,$fake)===0,'logout suppresses sends');
stock_query($db,"INSERT INTO account_devices(user_id,kind,token_hash,auth_version,expires_at) VALUES(1,'mobile',?,1,?)",[$device,time()+3600]);push_enqueue($db,$id,'expired-endpoint','test',['title'=>'Prueba','url'=>'cuenta.php']);push_dispatch($db,fn()=>['success'=>false,'status'=>410]);push_check((int)stock_query($db,'SELECT enabled FROM push_subscriptions WHERE id=?',[$id])->fetchColumn()===0,'410 disables endpoint');
// Reading or revoking a request before dispatch suppresses that pending delivery.
stock_query($db,'UPDATE push_subscriptions SET enabled=1 WHERE id=?',[$id]);stock_query($db,"UPDATE notifications SET read_at=CURRENT_TIMESTAMP WHERE type='stock_invitation'");$notice=stock_query($db,"SELECT * FROM notifications WHERE type='stock_invitation'")->fetch();push_enqueue($db,$id,'already-read','notice',[],(int)$notice['id']);push_check(push_dispatch($db,$fake)===0,'read notice cancelled');
$device2=hash('sha256','second-device');stock_query($db,"INSERT INTO account_devices(user_id,kind,token_hash,auth_version,expires_at) VALUES(2,'mobile',?,1,?)",[$device2,time()+3600]);push_enqueue($db,$id,'old-account','test',['title'=>'Viejo','url'=>'cuenta.php']);push_subscribe($db,2,$device2,$input);push_check((int)stock_query($db,'SELECT user_id FROM push_subscriptions WHERE id=?',[$id])->fetchColumn()===2,'endpoint reassigned explicitly');push_check(stock_query($db,"SELECT status FROM push_jobs WHERE event_key='old-account'")->fetchColumn()==='cancelled','old account queue cancelled');
// Exercise real encryption/signing with a mocked HTTP transport, never a real push service.
$http=new \GuzzleHttp\Handler\MockHandler([new \GuzzleHttp\Psr7\Response(201)]);$sender=new \Minishlink\WebPush\WebPush(['VAPID'=>['subject'=>'https://example.invalid','publicKey'=>$keys['public_key'],'privateKey'=>$keys['private_key']]],[],10,['handler'=>$http]);$report=$sender->sendOneNotification(\Minishlink\WebPush\Subscription::create($input),'private-test-message');push_check($report->isSuccess(),'real crypto transport smoke');push_check(!str_contains((string)$report->getRequest()->getBody(),'private-test-message'),'encrypted body');
echo "OK: migration44/idempotence, VAPID persistence, SSRF validation, queue/dedupe, selected kinds, grouped expiry, unread unchanged, logout/expired endpoints and real encryption over mocked HTTP.\n";
